CREATE TABLE IF NOT EXISTS clients ( id TEXT PRIMARY KEY, name TEXT NOT NULL, created_at INTEGER NOT NULL ); CREATE TABLE IF NOT EXISTS users ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, email TEXT NOT NULL, name TEXT NOT NULL, role TEXT NOT NULL CHECK (role IN ('super_admin','client_admin','manager','field_rep')), phone TEXT, password_hash TEXT, password_salt TEXT, active INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL ); CREATE UNIQUE INDEX IF NOT EXISTS users_client_email ON users(client_id, lower(email)); CREATE INDEX IF NOT EXISTS users_by_client ON users(client_id); CREATE TABLE IF NOT EXISTS territories ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, name TEXT NOT NULL, rep_id TEXT REFERENCES users(id) ON DELETE SET NULL ); CREATE TABLE IF NOT EXISTS properties ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, address1 TEXT NOT NULL, city TEXT, state TEXT, zip TEXT, lat REAL NOT NULL, lng REAL NOT NULL, status TEXT NOT NULL DEFAULT 'new', score INTEGER NOT NULL DEFAULT 50, opportunity_value INTEGER, owner_occupied INTEGER, roof_age_years INTEGER, square_feet INTEGER, last_outcome TEXT, last_visit_at INTEGER, next_action_at INTEGER, next_action_label TEXT, territory_id TEXT REFERENCES territories(id) ON DELETE SET NULL, assigned_rep_id TEXT REFERENCES users(id) ON DELETE SET NULL, tags TEXT, updated_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS properties_by_rep ON properties(client_id, assigned_rep_id); CREATE INDEX IF NOT EXISTS properties_by_territory ON properties(territory_id); CREATE TABLE IF NOT EXISTS contacts ( id TEXT PRIMARY KEY, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, name TEXT NOT NULL, phone TEXT, email TEXT, relationship TEXT, is_primary INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX IF NOT EXISTS contacts_by_property ON contacts(property_id); CREATE TABLE IF NOT EXISTS routes ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, date TEXT NOT NULL, name TEXT NOT NULL, started_at INTEGER ); CREATE INDEX IF NOT EXISTS routes_by_rep_date ON routes(rep_id, date); CREATE TABLE IF NOT EXISTS route_stops ( route_id TEXT NOT NULL REFERENCES routes(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, ord INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending', completed_at INTEGER, PRIMARY KEY (route_id, property_id) ); CREATE TABLE IF NOT EXISTS visits ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, started_at INTEGER NOT NULL, ended_at INTEGER, outcome TEXT, duration_ms INTEGER, start_lat REAL, start_lng REAL, start_accuracy REAL, next_action_at INTEGER, next_action_type TEXT ); CREATE INDEX IF NOT EXISTS visits_by_property ON visits(property_id); CREATE INDEX IF NOT EXISTS visits_by_rep_time ON visits(rep_id, started_at); CREATE TABLE IF NOT EXISTS notes ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, visit_id TEXT REFERENCES visits(id) ON DELETE SET NULL, body TEXT NOT NULL DEFAULT '', tags TEXT, author_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS notes_by_property ON notes(property_id); CREATE TABLE IF NOT EXISTS photos ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, visit_id TEXT REFERENCES visits(id) ON DELETE SET NULL, category TEXT NOT NULL, r2_key TEXT NOT NULL, width INTEGER, height INTEGER, bytes INTEGER, captured_lat REAL, captured_lng REAL, created_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS photos_by_property ON photos(property_id); CREATE TABLE IF NOT EXISTS appointments ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT NOT NULL REFERENCES properties(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, starts_at INTEGER NOT NULL, duration_min INTEGER NOT NULL DEFAULT 45, title TEXT NOT NULL, contact_id TEXT, notes TEXT ); CREATE INDEX IF NOT EXISTS appointments_by_rep ON appointments(rep_id, starts_at); CREATE TABLE IF NOT EXISTS tasks ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, property_id TEXT REFERENCES properties(id) ON DELETE CASCADE, title TEXT NOT NULL, due_at INTEGER NOT NULL, done INTEGER NOT NULL DEFAULT 0, kind TEXT NOT NULL DEFAULT 'follow_up' ); CREATE INDEX IF NOT EXISTS tasks_by_rep_due ON tasks(rep_id, due_at); CREATE TABLE IF NOT EXISTS activity ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, property_id TEXT REFERENCES properties(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, type TEXT NOT NULL, summary TEXT NOT NULL, outcome TEXT, at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS activity_by_client_time ON activity(client_id, at DESC); CREATE TABLE IF NOT EXISTS daily_stats ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL REFERENCES clients(id) ON DELETE CASCADE, rep_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, day TEXT NOT NULL, knocks INTEGER NOT NULL DEFAULT 0, conversations INTEGER NOT NULL DEFAULT 0, appointments INTEGER NOT NULL DEFAULT 0, quotes INTEGER NOT NULL DEFAULT 0, sold INTEGER NOT NULL DEFAULT 0, pipeline_value INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX IF NOT EXISTS daily_stats_by_client_day ON daily_stats(client_id, day); CREATE TABLE IF NOT EXISTS applied_mutations ( id TEXT PRIMARY KEY, client_id TEXT NOT NULL, user_id TEXT NOT NULL, kind TEXT NOT NULL, applied_at INTEGER NOT NULL ); CREATE INDEX IF NOT EXISTS applied_mutations_time ON applied_mutations(applied_at); CREATE TABLE IF NOT EXISTS invites ( token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_by TEXT REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, accepted_at INTEGER ); CREATE INDEX IF NOT EXISTS invites_by_user ON invites(user_id); CREATE TABLE IF NOT EXISTS sessions ( id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, expires_at INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0 ); CREATE INDEX IF NOT EXISTS sessions_by_user ON sessions(user_id);
